package project

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/ca-x/lazycat-github-action/internal/deployparams"
	toolkitbuild "github.com/lib-x/lzc-toolkit-go/build"
)

// ValidateDeployParams checks existing sources before buildscript execution.
// The final LPK is checked separately, including files generated by buildscript.
func ValidateDeployParams(ctx context.Context, root, buildConfig string) error {
	loaded, err := toolkitbuild.LoadConfig(ctx, root, buildConfig, map[string]string{})
	if err != nil {
		return fmt.Errorf("inspect build config: %w", err)
	}
	return validateDeployParams(root, loaded.Config.DeployParams)
}

func validateDeployParams(root, configured string) error {
	name := strings.TrimSpace(configured)
	if name == "" {
		name = "lzc-deploy-params.yml"
	}
	filename, err := beneath(root, name)
	if err != nil {
		return fmt.Errorf("inspect deployment parameters: %w", err)
	}
	if err := rejectSymlinkComponents(root, filename); err != nil {
		return fmt.Errorf("inspect deployment parameters: %w", err)
	}
	info, err := os.Stat(filename)
	if errors.Is(err, os.ErrNotExist) {
		return nil // A buildscript may generate this file.
	}
	if err != nil {
		return fmt.Errorf("stat deployment parameters: %w", err)
	}
	if !info.Mode().IsRegular() {
		return errors.New("deployment parameters must be a regular file")
	}
	file, err := os.Open(filename)
	if err != nil {
		return fmt.Errorf("open deployment parameters: %w", err)
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, deployparams.MaxDocumentBytes+1))
	if err != nil {
		return fmt.Errorf("read deployment parameters: %w", err)
	}
	relative, err := filepath.Rel(root, filename)
	if err != nil {
		return err
	}
	return deployparams.Validate(data, filepath.ToSlash(relative))
}
